package main

import (
	"bytes"
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"runtime"
	"strings"
	"sync"

	"go.yaml.in/yaml/v3"
)

// sqlc: every project with a sqlc.yaml in its directory has its queries
// generated by `just gen`, using the sqlc pinned in tools/sqlc/go.mod.

const (
	sqlcConfigFile = "sqlc.yaml"
	sqlcToolDir    = "tools/sqlc"
	sqlcHeader     = "// Code generated by sqlc. DO NOT EDIT."
)

// sqlcConfig is the part of a sqlc.yaml (version 2) gen needs.
type sqlcConfig struct {
	Version string `yaml:"version"`
	SQL     []struct {
		Gen struct {
			Go *struct {
				Out string `yaml:"out"`
			} `yaml:"go"`
		} `yaml:"gen"`
	} `yaml:"sql"`
}

type sqlcProject struct {
	Config string   // path to sqlc.yaml, relative to the repo root
	Outs   []string // output directories, relative to the repo root
}

// sqlcProjects finds each project's sqlc.yaml.
func sqlcProjects(r *Repo) ([]sqlcProject, error) {
	var out []sqlcProject
	var errs []error
	for _, p := range r.Projects {
		rel := filepath.ToSlash(filepath.Join(p.Dir, sqlcConfigFile))
		data, err := os.ReadFile(filepath.Join(r.Root, rel))
		if errors.Is(err, os.ErrNotExist) {
			continue
		}
		if err != nil {
			return nil, err
		}
		var cfg sqlcConfig
		if err := yaml.Unmarshal(data, &cfg); err != nil {
			errs = append(errs, fmt.Errorf("%s: %w", rel, err))
			continue
		}
		if cfg.Version != "2" {
			errs = append(errs, fmt.Errorf("%s: version must be \"2\"", rel))
			continue
		}
		sp := sqlcProject{Config: rel}
		for _, s := range cfg.SQL {
			if s.Gen.Go == nil || s.Gen.Go.Out == "" {
				continue
			}
			out := filepath.ToSlash(filepath.Join(p.Dir, s.Gen.Go.Out))
			if !strings.HasPrefix(out, p.Dir+"/") {
				errs = append(errs, fmt.Errorf("%s: out %q must be inside %s", rel, s.Gen.Go.Out, p.Dir))
				continue
			}
			sp.Outs = append(sp.Outs, out)
		}
		out = append(out, sp)
	}
	return out, errors.Join(errs...)
}

// GenerateSqlc runs `sqlc generate` for every project, in parallel. With
// check it runs `sqlc diff` instead and writes nothing.
func GenerateSqlc(r *Repo, check bool) error {
	projects, err := sqlcProjects(r)
	if err != nil || len(projects) == 0 {
		return err
	}
	bin, err := sqlcBinary(r.Root)
	if err != nil {
		return err
	}

	errs := make([]error, len(projects))
	sem := make(chan struct{}, runtime.NumCPU())
	var wg sync.WaitGroup
	for i, p := range projects {
		wg.Go(func() {
			sem <- struct{}{}
			defer func() { <-sem }()
			errs[i] = runSqlc(r.Root, bin, p, check)
		})
	}
	wg.Wait()
	return errors.Join(errs...)
}

func runSqlc(root, bin string, p sqlcProject, check bool) error {
	cmd := "generate"
	if check {
		cmd = "diff"
	} else {
		// sqlc never deletes output, so a removed query file would leave its
		// .sql.go behind. Clear what sqlc wrote last time first.
		for _, out := range p.Outs {
			if err := removeSqlcOutput(filepath.Join(root, out)); err != nil {
				return err
			}
		}
	}
	c := exec.Command(bin, cmd, "-f", filepath.Join(root, p.Config))
	c.Dir = root
	var buf bytes.Buffer
	c.Stdout, c.Stderr = &buf, &buf
	if err := c.Run(); err != nil {
		if check {
			return fmt.Errorf("%s: sqlc output is out of date or the queries are invalid (run `just gen`)\n%s", p.Config, buf.String())
		}
		return fmt.Errorf("%s: sqlc generate: %w\n%s", p.Config, err, buf.String())
	}
	if !check {
		fmt.Fprintf(os.Stderr, "generated %s\n", strings.Join(p.Outs, ", "))
	}
	return nil
}

// removeSqlcOutput deletes the files in dir that sqlc generated, leaving
// anything hand-written.
func removeSqlcOutput(dir string) error {
	entries, err := os.ReadDir(dir)
	if errors.Is(err, os.ErrNotExist) {
		return nil
	}
	if err != nil {
		return err
	}
	for _, e := range entries {
		if e.IsDir() || filepath.Ext(e.Name()) != ".go" {
			continue
		}
		path := filepath.Join(dir, e.Name())
		data, err := os.ReadFile(path)
		if err != nil {
			return err
		}
		if bytes.HasPrefix(data, []byte(sqlcHeader)) {
			if err := os.Remove(path); err != nil {
				return err
			}
		}
	}
	return nil
}

// sqlcBinary returns the pinned sqlc, building it once per version into the
// user cache dir (CI caches that dir; see .github/actions/setup).
func sqlcBinary(root string) (string, error) {
	h := sha256.New()
	for _, f := range []string{"go.mod", "go.sum"} {
		data, err := os.ReadFile(filepath.Join(root, sqlcToolDir, f))
		if err != nil {
			return "", err
		}
		h.Write(data)
	}
	cache, err := os.UserCacheDir()
	if err != nil {
		return "", err
	}
	name := "sqlc-" + hex.EncodeToString(h.Sum(nil))[:16]
	if runtime.GOOS == "windows" {
		name += ".exe"
	}
	bin := filepath.Join(cache, "laurel", name)
	if _, err := os.Stat(bin); err == nil {
		return bin, nil
	}

	if err := os.MkdirAll(filepath.Dir(bin), 0o755); err != nil {
		return "", err
	}
	fmt.Fprintf(os.Stderr, "building sqlc (%s)\n", sqlcToolDir)
	tmp := fmt.Sprintf("%s.tmp%d", bin, os.Getpid())
	c := exec.Command("go", "build", "-o", tmp, "github.com/sqlc-dev/sqlc/cmd/sqlc")
	c.Dir = filepath.Join(root, sqlcToolDir)
	c.Stdout, c.Stderr = os.Stderr, os.Stderr
	if err := c.Run(); err != nil {
		os.Remove(tmp)
		return "", fmt.Errorf("building sqlc: %w", err)
	}
	// Rename is atomic, so concurrent `just gen`s never run a half-written binary.
	if err := os.Rename(tmp, bin); err != nil {
		return "", err
	}
	return bin, nil
}
